import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.mRCPFc5l.js";const s="/assets/translation-provider.BDeIksrV.png",o="/assets/machine-translation.By3PtC9R.png",i="/assets/translation-review.BQUCqA1T.png",f=JSON.parse('{"title":"Machine Translation","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/06-machine-translation.md","filePath":"en_US/06-machine-translation.md"}'),l={name:"en_US/06-machine-translation.md"};function d(p,e,c,h,u,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="machine-translation" tabindex="-1">Machine Translation <a class="header-anchor" href="#machine-translation" aria-label="Permalink to &quot;Machine Translation&quot;">​</a></h1><p>Configure reusable translation providers and prompts, run selected episodes, and review results before applying them.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Create and test provider presets.</li><li>Manage reusable prompts and project glossary terms.</li><li>Choose episode ranges, reasoning, temperature, and concurrency.</li><li>Review failures and translation conflicts without overwriting work silently.</li></ul><h2 id="configure-a-translation-provider" tabindex="-1">Configure a translation provider <a class="header-anchor" href="#configure-a-translation-provider" aria-label="Permalink to &quot;Configure a translation provider&quot;">​</a></h2><p>Open <strong>Machine Translation → Manage Providers</strong>. Create a preset with a name, Base URL, API key, model, and supported capabilities. Configure proxy or network options only when required by the service.</p><p><img src="'+s+`" alt="Translation provider manager with a fictional provider"></p><p>Use provider credentials supplied for your own account. Do not place real API keys in project folders, screenshots, diagnostics, or shared documentation. Save the preset, return to the panel, and select it.</p><h2 id="custom-request-parameters-and-headers" tabindex="-1">Custom request parameters and headers <a class="header-anchor" href="#custom-request-parameters-and-headers" aria-label="Permalink to &quot;Custom request parameters and headers&quot;">​</a></h2><p>The Request Options card sits between Capabilities and Network. It contains two multiline YAML fields, Extra Parameters (YAML format, optional) and Extra Headers (YAML format, optional), with the explanatory text at the bottom inside the card.</p><p>Gray placeholder text is only an example; it is never saved or sent. Adapt the examples to your provider documentation and actual needs, or leave the fields empty. <strong>Incorrect settings or unsupported parameters may cause translation failures.</strong></p><h3 id="extra-parameters-and-reasoning-priority" tabindex="-1">Extra parameters and reasoning priority <a class="header-anchor" href="#extra-parameters-and-reasoning-priority" aria-label="Permalink to &quot;Extra parameters and reasoning priority&quot;">​</a></h3><p>Extra parameters are added directly to the request body and support nested objects. For example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">reasoning_effort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">high</span></span></code></pre></div><p>The Reasoning selection in the Machine Translation panel determines the final <code>reasoning_effort</code> value:</p><table tabindex="0"><thead><tr><th>Panel Reasoning</th><th>YAML configuration</th><th>Sent to the provider</th></tr></thead><tbody><tr><td>Default</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: high</code></td></tr><tr><td>Low</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: low</code></td></tr><tr><td>None</td><td><code>reasoning_effort: high</code></td><td><code>reasoning_effort: none</code></td></tr><tr><td>Default</td><td>No <code>reasoning_effort</code></td><td>Parameter omitted; provider default applies</td></tr></tbody></table><p>This priority rule applies only to <code>reasoning_effort</code>. Other YAML parameters, such as <code>thinking</code> and <code>reasoning</code>, do not change with the panel selection. Consult your provider documentation for supported combinations. Force skip reasoning independently controls the assistant prefill message and is unaffected by request options.</p><h3 id="extra-headers-storage-and-protection" tabindex="-1">Extra headers, storage and protection <a class="header-anchor" href="#extra-headers-storage-and-protection" aria-label="Permalink to &quot;Extra headers, storage and protection&quot;">​</a></h3><p>Header names and values must be strings, for example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Custom-Feature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enabled&quot;</span></span></code></pre></div><p>Save Preset stores both YAML fields with the other global translation settings. Reopen the manager and select the preset to read them. Import/export preserves the original text, comments and line breaks. Custom headers are stored and exported in plaintext; existing multi-window conflict handling still applies.</p><p>Application-controlled fields, including model, messages, temperature, streaming, authorization and HTTP transport controls, cannot be overridden here. Invalid configuration blocks saving or sending a request. Providers may still reject unsupported fields or combinations that pass application validation.</p><p>Use a single YAML mapping without tags, anchors or aliases. Each field is limited to 64 KiB and 20 nesting levels.</p><h2 id="manage-translation-prompts" tabindex="-1">Manage translation prompts <a class="header-anchor" href="#manage-translation-prompts" aria-label="Permalink to &quot;Manage translation prompts&quot;">​</a></h2><p>Open <strong>Manage Prompts</strong> to store reusable instructions. A prompt may define tone, terminology, output restrictions, and context handling. Prompts are application-level presets; the project remembers the most recently selected preset. Choose <strong>No custom prompt</strong> to use only the built-in translation rules, without adding the global default custom prompt. This choice is saved with the project. A new project inherits the global default prompt preset, if one exists, until you make a selection.</p><p>If shared provider/prompt settings change in another window, choose whether to reload the external version or overwrite it with your current edits.</p><h2 id="set-the-translation-scope" tabindex="-1">Set the translation scope <a class="header-anchor" href="#set-the-translation-scope" aria-label="Permalink to &quot;Set the translation scope&quot;">​</a></h2><p>Enter <code>all</code>, a single episode, ranges, spaces, or commas, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>all</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>1 3</span></span>
<span class="line"><span>1-3,8</span></span></code></pre></div><p>The panel shows how many episodes are available. Invalid or missing episodes are rejected before a request is sent.</p><h2 id="adjust-translation-options" tabindex="-1">Adjust translation options <a class="header-anchor" href="#adjust-translation-options" aria-label="Permalink to &quot;Adjust translation options&quot;">​</a></h2><p><img src="`+o+'" alt="Machine Translation panel with provider, glossary, options, and three-episode scope"></p><ul><li><strong>Target Language</strong> comes from project settings and can be adjusted for the task.</li><li><strong>Prompt</strong> adds reusable instructions.</li><li><strong>Temperature</strong> controls variation where supported.</li><li><strong>Reasoning</strong> sends the explicit panel choice as <code>reasoning_effort</code>. Default uses the provider YAML value if present, otherwise omits the field. Provider/model support varies.</li><li><strong>Concurrency</strong> controls parallel requests; reduce it when the service rate-limits.</li><li><strong>Force skip reasoning (Experimental)</strong> is off by default. It forces an assistant-role prefill message to try to skip reasoning. Unsupported models may produce unexpected results; enabling it is generally not recommended. Hover over the option for details. Existing saved choices are preserved, independently of provider YAML options.</li><li><strong>Glossary</strong> uses one <code>source = target</code> term per line.</li></ul><h2 id="run-and-cancel-translation" tabindex="-1">Run and cancel translation <a class="header-anchor" href="#run-and-cancel-translation" aria-label="Permalink to &quot;Run and cancel translation&quot;">​</a></h2><p>Click <strong>Run Translation</strong>. The task log shows progress, failures, and cancellation. You can cancel an active job; completed responses are still preserved for review/backup where applicable.</p><p>GridSubStudio sends only the subtitle/context required by the task to the configured service. Review your provider&#39;s privacy and retention policy before processing sensitive material.</p><h2 id="handle-translation-failures" tabindex="-1">Handle translation failures <a class="header-anchor" href="#handle-translation-failures" aria-label="Permalink to &quot;Handle translation failures&quot;">​</a></h2><p>Failures remain visible by row or request. Common causes include invalid credentials, an incorrect Base URL/model, unsupported options, timeouts, proxy errors, rate limits, and invalid episode scope. Correct the cause and rerun only the needed episodes.</p><h2 id="review-and-apply-translations" tabindex="-1">Review and apply translations <a class="header-anchor" href="#review-and-apply-translations" aria-label="Permalink to &quot;Review and apply translations&quot;">​</a></h2><p>Existing translations are never silently replaced. When generated text conflicts with current text, the review dialog groups rows by episode.</p><p><img src="'+i+'" alt="Translation conflict review for three episodes"></p><ol><li>Compare source, existing translation, and new translation.</li><li>Check individual rows or an entire episode.</li><li>Edit generated text when necessary.</li><li>Click <strong>Apply Checked Replacements</strong>, or <strong>Keep Existing</strong> to apply none.</li></ol><p>Unchecked rows retain their existing translations. Save the project after applying reviewed changes.</p><h2 id="open-translation-backups" tabindex="-1">Open translation backups <a class="header-anchor" href="#open-translation-backups" aria-label="Permalink to &quot;Open translation backups&quot;">​</a></h2><p>Click <strong>Open Backup Folder</strong> to inspect stored task results. Backups help recover or audit generated text but do not replace normal project saves. Keep them with appropriate access controls because they may contain subtitle content.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Run Translation is disabled:</strong> use project mode, import subtitles, select an enabled provider, and enter a valid scope.</li><li><strong>All requests fail:</strong> verify Base URL, API key, model, proxy, and provider availability.</li><li><strong>Only some rows fail:</strong> inspect the task log and rerun the affected episodes after correction.</li><li><strong>No conflict dialog appears:</strong> there may be no generated rows or no existing translations to replace.</li></ul>',47)])])}const b=t(l,[["render",d]]);export{f as __pageData,b as default};
